using Microsoft.Data.Sqlite;using Archy.Features.Workspaces.AcquireWorkspaceLock;using Archy.Features.Workspaces.InitializeWorkspace;using Archy.SharedKernel.Primitives;
namespace Archy.Features.Duplicates.DuplicateFindings;
/// <summary>Read-only identity lookup used by query surfaces; it returns exact persisted pair identities and never infers a new duplicate.</summary>
public sealed class DuplicateFindingLookup(IWorkspaceLockManager lockManager):IDuplicateFindingLookup { public async ValueTask<Result<IReadOnlyList<string>>> FindIdsByTargetAsync(WorkspaceStateLocation location,string targetStableId,CancellationToken cancellationToken){ArgumentNullException.ThrowIfNull(location);ArgumentException.ThrowIfNullOrWhiteSpace(targetStableId);var lease=await lockManager.AcquireAsync(location,WorkspaceLockMode.Read,TimeSpan.FromSeconds(30),cancellationToken);if(!lease.IsSuccess)return ResultFactory.Failure<IReadOnlyList<string>>(lease.Problem!);using var held=lease.Value;try{SQLitePCL.Batteries_V2.Init();await using var c=new SqliteConnection($"Data Source={location.DatabasePath}");await c.OpenAsync(cancellationToken);await using var q=c.CreateCommand();q.CommandText="SELECT finding_id FROM duplicate_finding_identities WHERE workspace_id=$workspaceId AND (left_target_stable_id=$target OR right_target_stable_id=$target) ORDER BY finding_id;";q.Parameters.AddWithValue("$workspaceId",location.WorkspaceId);q.Parameters.AddWithValue("$target",targetStableId);await using var r=await q.ExecuteReaderAsync(cancellationToken);var ids=new List<string>();while(await r.ReadAsync(cancellationToken))ids.Add(r.GetString(0));return ResultFactory.Success<IReadOnlyList<string>>([..ids]);}catch(SqliteException e){return ResultFactory.Failure<IReadOnlyList<string>>(Problem.Storage($"Archy could not query duplicate findings: {e.Message}"));}}}
